// Simplified Chinese overlays for the Security figure teaching boards,
// keyed by example id like every other built-in overlay (see
// examples.zh.js). The boards are generated by buildSecurityIllustration,
// so their generated ids are pinned to the authored analysis ids (items,
// "from>to" links, target/outcome panels, scenes, "<scene>-chapter") by
// stableBoardIds in src/examples-security-board.js; these entries name
// those ids on every module load. Only text translates — card labels and
// notes, zone labels, word-like wire labels, the scene summary note, the
// authored overview chapters and the generated walkthrough chapter. Item
// values (card part numbers), evidence citations, ids and geometry stay
// byte-identical, so the localized copy round-trips like the original.
const SOURCE = '来源', INFERENCE = '推断';
// A generated card note reads "scene / panel", the item's value, the
// static-reading line with its basis, the translated finding, then the
// authored evidence citation.
const note = (scene, panel, value, basis, finding, evidence) =>
  `${scene} / ${panel}\n${value}\n静态阅读；未执行。[${basis}]\n${finding}\n证据：${evidence}`;

